CREATE DATABASE IF NOT EXISTS memory_museum CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE memory_museum;
CREATE TABLE IF NOT EXISTS eras (id INT PRIMARY KEY, label VARCHAR(40) NOT NULL, image VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS items (id INT AUTO_INCREMENT PRIMARY KEY, era_id INT NOT NULL, type ENUM('official','citizen') NOT NULL DEFAULT 'citizen', title VARCHAR(120) NOT NULL, description TEXT NOT NULL, image_path VARCHAR(255), password_hash VARCHAR(255), status ENUM('active','hidden','deleted') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (era_id) REFERENCES eras(id), INDEX(type,status,created_at));
CREATE TABLE IF NOT EXISTS comments (id INT AUTO_INCREMENT PRIMARY KEY, item_id INT NOT NULL, body TEXT NOT NULL, password_hash VARCHAR(255) NOT NULL, status ENUM('active','hidden','deleted') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reports (id INT AUTO_INCREMENT PRIMARY KEY, target_type ENUM('item','comment') NOT NULL, target_id INT NOT NULL, reason VARCHAR(60) NOT NULL, fingerprint CHAR(64) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY unique_report(target_type,target_id,fingerprint), INDEX(target_type,target_id));
INSERT INTO eras (id,label,image) VALUES (1960,'1960 ~ 1970','/images/1960.jpg'),(1970,'1970 ~ 1980','/images/1970.jpg'),(1980,'1980 ~ 1990','/images/1980.jpg'),(1990,'1990년대','/images/1990.jpg'),(2000,'2000 ~ 2010','/images/2000.jpg') ON DUPLICATE KEY UPDATE label=VALUES(label),image=VALUES(image);

CREATE TABLE IF NOT EXISTS wanted_posts (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120) NOT NULL,description TEXT NOT NULL,password_hash VARCHAR(255) NOT NULL,status ENUM('active','deleted') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status,created_at));
CREATE TABLE IF NOT EXISTS wanted_comments (id INT AUTO_INCREMENT PRIMARY KEY,post_id INT NOT NULL,body TEXT NOT NULL,password_hash VARCHAR(255) NOT NULL,status ENUM('active','deleted') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(post_id) REFERENCES wanted_posts(id) ON DELETE CASCADE);
